import{_ as s,o as i,c as t,ah as a}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"cocotb and the Celox CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cocotb.md","filePath":"guide/cocotb.md"}'),n={name:"guide/cocotb.md"};function o(l,e,d,h,p,c){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="cocotb-and-the-celox-cli" tabindex="-1">cocotb and the Celox CLI <a class="header-anchor" href="#cocotb-and-the-celox-cli" aria-label="Permalink to &quot;cocotb and the Celox CLI&quot;">​</a></h1><p>Celox can compile a Veryl or SystemVerilog design into a native executable that runs ordinary <a href="https://www.cocotb.org/" target="_blank" rel="noreferrer">cocotb</a> tests through VPI. The generated executable contains the compiled design and the Celox runtime; it does not need the HDL sources when it runs.</p><h2 id="build-the-cli" tabindex="-1">Build the CLI <a class="header-anchor" href="#build-the-cli" aria-label="Permalink to &quot;Build the CLI&quot;">​</a></h2><p>The CLI is currently built from the Celox source tree:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox-vpi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemverilog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox</span></span></code></pre></div><p>The <code>run</code> command below needs no Python installation. For VPI tests, install cocotb into the Python environment you want to use:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cocotb</span></span></code></pre></div><p>The repository dev container already includes cocotb 2.0.1 and Verilator.</p><h2 id="run-an-hdl-testbench-directly" tabindex="-1">Run an HDL testbench directly <a class="header-anchor" href="#run-an-hdl-testbench-directly" aria-label="Permalink to &quot;Run an HDL testbench directly&quot;">​</a></h2><p>Use the same command for a SystemVerilog testbench and a Veryl native <code>#[test]</code> module:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/types.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Dut.sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/Top.sv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span></span></code></pre></div><p>For SystemVerilog, pass <code>.sv</code> or <code>.v</code> sources in compilation order. The command uses four-state simulation and runs until <code>$finish</code> or no scheduled events remain. For Veryl, pass one project entry file: Celox discovers <code>Veryl.toml</code> and collects the project&#39;s sources and dependencies. A standalone Veryl file also works. Select the native testbench module with <code>--top</code>. Veryl uses the existing native testbench executor; a test may also complete by falling through its initial blocks.</p><p>The command uses the existing frontends&#39; supported language subsets; unsupported constructs produce compilation diagnostics. <code>-O O0</code>, <code>-O O1</code> (default), and <code>-O O2</code> select the existing compiler optimization levels.</p><p>Successful completion returns status 0. Compilation errors, runtime errors, assertion failures, <code>$error</code>, <code>$fatal</code>, lost runtime events, and exhausted execution limits return status 1. SV <code>$stop</code> also returns status 1 because this command has no interactive debugger. Invalid command arguments return status 2. SV <code>$display</code>/<code>$write</code> output goes to stdout; the existing Veryl native testbench executor sends its HDL output to stderr.</p><p><code>--max-steps N</code> sets a positive execution limit (default: 1000000). It counts scheduler steps for SV and testbench ticks for Veryl. Reaching the Veryl tick limit before completion fails the command. This limit does not bound compilation or work within a single step/tick; use an external process timeout when a wall clock limit is needed. Source languages cannot be mixed in one invocation.</p><h2 id="compile-a-design" tabindex="-1">Compile a design <a class="header-anchor" href="#compile-a-design" aria-label="Permalink to &quot;Compile a design&quot;">​</a></h2><p>Pass one source in the Veryl project and name the top-level module:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>Celox finds <code>Veryl.toml</code> from the source path and includes the project&#39;s source files and dependencies. For a standalone source outside a Veryl project, it compiles that file alone. The output defaults to <code>celox.out</code> when <code>-o</code> is omitted.</p><p>For standalone SystemVerilog, pass a <code>.sv</code> file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.sv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>This compiles only the specified file, including any child modules defined in it, using Celox&#39;s supported SystemVerilog subset. It does not discover a <code>Veryl.toml</code> project or additional SystemVerilog source files.</p><h2 id="run-cocotb" tabindex="-1">Run cocotb <a class="header-anchor" href="#run-cocotb" aria-label="Permalink to &quot;Run cocotb&quot;">​</a></h2><p>Suppose <code>test/test_top.py</code> contains a cocotb test. Run the generated executable from a directory where that module is importable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span></span></code></pre></div><p>The executable automatically:</p><ul><li>uses <code>python3</code> and locates its cocotb VPI adapter and libpython;</li><li>supplies the compiled top-level name to cocotb;</li><li>writes <code>results.xml</code> and returns a failing exit status when a test fails.</li></ul><p>Use another Python environment or result path explicitly when needed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --results-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/results.xml</span></span></code></pre></div><p><code>--test-filter REGEX</code> selects matching tests; <code>--testcase NAME</code> is also available for cocotb&#39;s legacy test selection. <code>--vpi PATH</code> overrides automatic VPI adapter discovery. The corresponding cocotb environment variables remain supported for existing automation: <code>PYGPI_PYTHON_BIN</code>, <code>LIBPYTHON_LOC</code>, <code>CELOX_COCOTB_VPI</code>, <code>COCOTB_TEST_MODULES</code>, <code>COCOTB_TEST_FILTER</code>, and <code>COCOTB_RESULTS_FILE</code>.</p><h2 id="current-compatibility" tabindex="-1">Current compatibility <a class="header-anchor" href="#current-compatibility" aria-label="Permalink to &quot;Current compatibility&quot;">​</a></h2><p>The compatibility layer covers cocotb 2.0 paths for module and signal discovery, immediate/deposit/force/release writes, scalar and vector values, simulation time, and the Start, ReadWrite, ReadOnly, NextTimeStep, Timer, ValueChange, and End callback regions.</p><p>Packed bit handles, delayed VPI writes, unpacked-array indexing, and derived/cascaded clock scheduling are not yet supported.</p>`,33)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
